INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64829226', 64829226, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'KELURAHAN TEGAL ALUR - JAKBAR', 'Belanja Jasa Tenaga Penanganan Prasarana dan Sarana Umum (Petugas PPSU – Kelurahan Tegal Alur)', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Barat (Kota)', 5752947226, 'December 2025', 'APBD', 1, 1, '86 Paket', '1. Penanganan Prasarana dan Sarana Jalan/gang 2. Penanganan Prasaran dan Sarana Saluran 3. Penanganan Prasarana dan Sarana Taman 4. Penanganan Prasarana dan Sarana Kebersihan 5. Penanganan Prasarana dan Sarana penerangan jalan umum 6. Melakukan tugas-tugas yang bersifat non fisik atas perintah lurah sesuai kebutuhan organisasi kelurahan', '1. Penanganan Prasarana dan Sarana Jalan/gang, terdiri dari : a. Perbaikan Jalan berlubang di Wilayah Kelurahan; b. Perbaikan dan pengecatan kastin, perbaikan pembatas jalan yang rusak di wilayah kelurahan; c. Perbaikan trotoar jalan yang rusak dan/atau berlubang diwilayah kelurahan; d. Memonitor dan merapikan tutup saluran air tutup vankom diatas saluran yang bergeser / tidak pada tempatnya. 2. Penanganan Prasaran dan Sarana Saluran, terdiri dari : a. Perbaikan saluran rusak dijalan lingkungan/lokal; b. Pengurasan saluran, tali, dan mulut air yang mampet dijalan lingkungan/lokal; c. Pelaporan segera pembangunan atau aktivitas yang berpotensi mengganggu saluran termasuk penutupan saluran air dan tali-tali air / mulut air kepada perangkat daerah terkait melalui lurah. 3. Penanganan Prasarana dan Sarana Taman, terdiri dari : a. Pohon tumbang dan/atau patah diwilayah kelurahan; b. Pembabatan rumput dan semak diwilayah kelurahan; c. Pengambilan pot rusak yang mengganggu lingkungan; d. Pelaporan segera penebangan pohon pelindung tanpa izin kepada Perangkat Daerah terkait melalui Lurah. 4. Penanganan Prasarana dan Sarana Kebersihan, terdiri dari : a. Penyapuan Jalan diwilayah kelurahan; b. Pembersihan timbunan sampah liar dan ceceran sampah diwilayah kelurahan; c. Pembersihan coretan-coretan dan keping informasi diruang public wilayah kelurahan; d. Pembersihan jalan, saluran, taman, jalur hijau, area pantai, bangunan dan/atau ruang public lainnya diwilayah kelurahan. 5. Penanganan Prasarana dan Sarana penerangan jalan umum, terdiri dari : a. Penanganan penerangan jalan umum yang rusak dan/atau membahayakan keselamatan; b. Penanganan sementara lampu jalan lokal yang rusak/mati dengan menggunakan lampu jalan sementara untuk menerangi jalan sesuai dengan kebutuhan; c. Penanganan dan pelaporan jaringan utilitas yang mengganggu kepentingan umumdi jalan lingkungan / lokal; d. Pelaporan lampu penerangan jalan yang dibutuhkan warga dan yang tidak berfungsi. 6. Melakukan tugas-tugas yang bersifat non fisik atas perintah lurah sesuai kebutuhan organisasi kelurahan. a. Membantu kegiatan administrasi kantor b. Mengantar surat c. Monitoring kegiatan d. Tugas-tugas lainnya sesuai arahan pimpinan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1774117);
