INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64809033', 64809033, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENYUSUNAN ANALISIS KEBUTUHAN PENGELOLAN DAN PEMANFAATAN DATA DAN INFORMASI SPASIAL INFRASTRUKTUR', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 99600000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 1, '11', 'Pengolahan Data & Integrasi. Sinkronisasi data dari berbagai sumber, termasuk penarikan data dari K/L dan Pemda melalui API atau portal satu data. Kegiatan mencakup transformasi sistem proyeksi koordinat, penyatuan format data yang berbeda, serta penggabungan tabel atribut agar database memiliki struktur yang seragam dan siap diintegrasikan ke dalam platform dashboard', '1. Pendidikan minimal Strata 1 (Sarjana) dari jurusan geografi, perencanaan wilayah dan kota, geodesi, teknik sipil (dibuktikan dengan ijazah); 2. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta (dibuktikan dengan kontrak); 3. Diutamakan Tenaga ahli dalam negeri (dibuktikan dengan kewarganegaraan Indonesia seperti Kartu Tanda Penduduk); 4. Memiliki pengalaman kerja minimum 2 (dua) tahun di bidang sejenis terkait analisis penginderaan jauh, pemodelan spasial, pembuatan peta tematik atau analisis berbasis GIS; 5. Memiliki pengalaman kerja dengan nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai total HPS/Pagu Anggaran; 6. Memiliki pengalaman pengelolaan basis data spasial; 7. Menguasai perangkat lunak berbasis GIS seperti ArcGIS Pro, QGIS; 8. Memiliki pemahaman dasar mengenai standar geospasial nasional, dan kaidah penyusunan peta untuk kebutuhan perencanaan;', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 1774299);
